import {
  createTraitVector,
  type TraitEffects,
} from "@player-dna/player-matching";
import type {
  PlayerDNAProfile,
  RoleFamily,
  StrongFoot,
} from "../lib/scoring/types";

// MVP player profiles are hand-curated style priors, not official ratings or
// live data. Later versions can replace these seeds with a calibrated data layer.
type PlayerSeed = {
  id: string;
  name: string;
  roleFamily: RoleFamily;
  positions: string[];
  strongFoot: StrongFoot;
  preferredZones: string[];
  archetype: string;
  traits: TraitEffects;
  tags: string[];
  summary: string;
};

function player(seed: PlayerSeed): PlayerDNAProfile {
  return {
    ...seed,
    traits: createTraitVector(seed.traits),
  };
}

